public class Amdahl {
    static double speedup(double p, int n) { return 1.0 / ((1 - p) + p / n); }
    public static void main(String[] args) {
        System.out.println("cores available here: "
            + Runtime.getRuntime().availableProcessors() + " (varies)");
        double[] ps = {0.50, 0.90, 0.95};
        int[] ns = {2, 4, 8, 16, 1000};
        for (double p : ps) {
            StringBuilder sb = new StringBuilder(String.format("parallel fraction %.2f:", p));
            for (int n : ns) sb.append(String.format("  n=%d -> %.2fx", n, speedup(p, n)));
            System.out.println(sb);
        }
    }
}

