                    + Thread.currentThread().isInterrupted());
            }
        });
        sleeper.start();
        sleeper.interrupt();
        sleeper.join();

        Thread spinner = new Thread(() -> {
            long n = 0;
            while (!Thread.currentThread().isInterrupted()) n++;
            System.out.println("spinner: saw interrupt, stopping");
        });
        spinner.start();
        Thread.sleep(50);
        spinner.interrupt();
        spinner.join();
        System.out.println("done");
    }
}

import java.util.concurrent.atomic.AtomicInteger;

public class Race {
    static int plain = 0;
    static volatile int vol = 0;
    static int locked = 0;
    static final Object LOCK = new Object();
    static final AtomicInteger atomic = new AtomicInteger();

    public static void main(String[] args) throws Exception {
        final int perThread = 1_000_000;
        Runnable r = () -> {
            for (int i = 0; i < perThread; i++) {
                plain++;
                vol++;
                synchronized (LOCK) { locked++; }
                atomic.incrementAndGet();
            }
        };
        Thread a = new Thread(r), b = new Thread(r);
        a.start(); b.start();
        a.join(); b.join();
        System.out.println("expected          : " + 2 * perThread);
        System.out.println("plain int         : " + plain);
        System.out.println("volatile int      : " + vol);
        System.out.println("synchronized      : " + locked);
        System.out.println("AtomicInteger     : " + atomic.get());
    }
}

