import java.util.ArrayDeque;
import java.util.Queue;

public class BoundedBuffer<T> {
    private final Queue<T> queue = new ArrayDeque<>();
    private final int capacity;
    public BoundedBuffer(int capacity) { this.capacity = capacity; }

    public synchronized void put(T item) throws InterruptedException {
        while (queue.size() == capacity) wait();     // loop, never "if"
        queue.add(item);
        notifyAll();
    }
    public synchronized T take() throws InterruptedException {
        while (queue.isEmpty()) wait();
        T item = queue.remove();
        notifyAll();
        return item;
    }

    public static void main(String[] args) throws Exception {
        BoundedBuffer<Integer> buf = new BoundedBuffer<>(3);
        Thread producer = new Thread(() -> {
            try {
                for (int i = 1; i <= 8; i++) buf.put(i);
                buf.put(-1);                         // poison pill
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        }, "producer");
        Thread consumer = new Thread(() -> {
            try {
                int sum = 0;
                for (int v; (v = buf.take()) != -1; ) sum += v;
                System.out.println("consumer sum = " + sum);
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        }, "consumer");
        producer.start(); consumer.start();
        producer.join(); consumer.join();
    }
}

