import java.text.SimpleDateFormat;
import java.util.Date;

public class Confine {
    // SimpleDateFormat is NOT thread-safe; give each thread its own copy.
    private static final ThreadLocal<SimpleDateFormat> FMT =
        ThreadLocal.withInitial(() -> new SimpleDateFormat("yyyy-MM-dd"));

    private static final ThreadLocal<String> REQUEST_ID = new ThreadLocal<>();

    static void handle(String id) {
        REQUEST_ID.set(id);
        try {
            step();
        } finally {
            REQUEST_ID.remove();                 // essential in thread pools
        }
    }
    static void step() {
        System.out.println(Thread.currentThread().getName() + " handling " + REQUEST_ID.get()
            + ", date " + FMT.get().format(new Date(0L)));
    }
    public static void main(String[] args) throws Exception {
        Thread a = new Thread(() -> handle("req-1"), "t-a");
        Thread b = new Thread(() -> handle("req-2"), "t-b");
        a.start(); b.start(); a.join(); b.join();
        System.out.println("main sees: " + REQUEST_ID.get());
    }
}

