import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class LockDemo {
    static class Account {
        private final ReentrantLock lock = new ReentrantLock();
        private long balance;

        Account(long balance) { this.balance = balance; }

        void deposit(long amount) {
            lock.lock();                 // acquire BEFORE the try block
            try {
                balance += amount;
            } finally {
                lock.unlock();           // always release in finally
            }
        }

        boolean tryDeposit(long amount, long millis) throws InterruptedException {
            if (!lock.tryLock(millis, TimeUnit.MILLISECONDS)) {
                return false;            // could not get the lock in time
            }
            try {
                balance += amount;
                return true;
            } finally {
                lock.unlock();
            }
        }

        long balance() {
            lock.lock();
            try { return balance; } finally { lock.unlock(); }
        }

        ReentrantLock lock() { return lock; }
    }

    public static void main(String[] args) throws Exception {
        Account acc = new Account(100);
        acc.deposit(50);
        System.out.println("balance = " + acc.balance());

        // Reentrancy: the same thread may lock again; hold count goes up.
        acc.lock().lock();
        acc.lock().lock();
        System.out.println("hold count = " + acc.lock().getHoldCount());
        acc.lock().unlock();
        acc.lock().unlock();
        System.out.println("locked after unlocks? " + acc.lock().isLocked());

        // Another thread holds the lock; tryLock with a timeout gives up.
        Thread holder = new Thread(() -> {
            acc.lock().lock();
            try {
                Thread.sleep(500);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } finally {
                acc.lock().unlock();
            }
        });
        holder.start();
        Thread.sleep(100);               // let the holder take the lock
        System.out.println("tryLock(100ms) = " + acc.lock().tryLock(100, TimeUnit.MILLISECONDS));
        System.out.println("tryDeposit while held = " + acc.tryDeposit(10, 50));
        holder.join();
        System.out.println("tryDeposit after release = " + acc.tryDeposit(10, 50));
        System.out.println("final balance = " + acc.balance());
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

public class BoundedBuffer {
    static class Buffer<T> {
        private final Deque<T> items = new ArrayDeque<>();
        private final int capacity;
        private final ReentrantLock lock = new ReentrantLock();
        private final Condition notFull = lock.newCondition();
        private final Condition notEmpty = lock.newCondition();

        Buffer(int capacity) { this.capacity = capacity; }

        void put(T item) throws InterruptedException {
            lock.lock();
            try {
                while (items.size() == capacity) {
                    notFull.await();        // releases the lock while waiting
                }
                items.addLast(item);
                notEmpty.signal();          // wake one consumer only
            } finally {
                lock.unlock();
            }
        }

        T take() throws InterruptedException {
            lock.lock();
            try {
                while (items.isEmpty()) {
                    notEmpty.await();
                }
                T item = items.removeFirst();
                notFull.signal();           // wake one producer only
                return item;
            } finally {
                lock.unlock();
            }
        }
    }

    public static void main(String[] args) throws Exception {
        Buffer<Integer> buf = new Buffer<>(3);
        int n = 1000;
        long[] sum = new long[1];

        Thread producer = new Thread(() -> {
            try {
                for (int i = 1; i <= n; i++) buf.put(i);
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });
        Thread consumer = new Thread(() -> {
            try {
                for (int i = 1; i <= n; i++) sum[0] += buf.take();
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });
        producer.start();
        consumer.start();
        producer.join();
        consumer.join();
        System.out.println("consumed sum = " + sum[0] + " (expected " + (n * (n + 1L) / 2) + ")");
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class RwDemo {
    static class PriceCache {
        private final Map<String, Integer> prices = new HashMap<>();
        private final ReentrantReadWriteLock rw = new ReentrantReadWriteLock();

        Integer get(String sku) {
            rw.readLock().lock();            // many readers may hold this at once
            try {
                return prices.get(sku);
            } finally {
                rw.readLock().unlock();
            }
        }

        void put(String sku, int price) {
            rw.writeLock().lock();           // exclusive: no readers, no other writers
            try {
                prices.put(sku, price);
            } finally {
                rw.writeLock().unlock();
            }
        }

        ReentrantReadWriteLock lock() { return rw; }
    }

    public static void main(String[] args) {
        PriceCache cache = new PriceCache();
        cache.put("book", 499);
        System.out.println("book = " + cache.get("book"));
        var rw = cache.lock();
        rw.readLock().lock();
        rw.readLock().lock();
        System.out.println("read locks held = " + rw.getReadLockCount());
        rw.readLock().unlock();
        rw.readLock().unlock();

        // Downgrading is allowed: take the read lock while still holding the write lock.
        rw.writeLock().lock();
        rw.readLock().lock();
        rw.writeLock().unlock();
        System.out.println("downgraded: write locked = " + rw.isWriteLocked()
                + ", readers = " + rw.getReadLockCount());
        rw.readLock().unlock();

        // Upgrading is NOT: a thread holding the read lock that asks for the write lock
        // would wait for itself. We show it with tryLock so the program does not hang.
        rw.readLock().lock();
        boolean upgraded = rw.writeLock().tryLock();
        System.out.println("upgrade with tryLock succeeded? " + upgraded);
        rw.readLock().unlock();
    }
}

import java.util.concurrent.locks.StampedLock;

public class StampedDemo {
    static class Point {
        private double x, y;
        private final StampedLock sl = new StampedLock();

        void move(double dx, double dy) {
            long stamp = sl.writeLock();
            try {
                x += dx;
                y += dy;
            } finally {
                sl.unlockWrite(stamp);
            }
        }
        double distanceFromOrigin() {
            long stamp = sl.tryOptimisticRead();     // no lock taken, just a version stamp
            double cx = x, cy = y;                   // read the fields into locals
            if (!sl.validate(stamp)) {               // did a write happen meanwhile?
                stamp = sl.readLock();               // fall back to a real read lock
                try {
                    cx = x;
                    cy = y;
                } finally {
                    sl.unlockRead(stamp);
                }
            }
            return Math.hypot(cx, cy);
        }
    }

    public static void main(String[] args) throws Exception {
        Point p = new Point();
        p.move(3, 4);
        System.out.println("distance = " + p.distanceFromOrigin());

        StampedLock sl = new StampedLock();
        long s = sl.tryOptimisticRead();
        System.out.println("valid before write? " + sl.validate(s));
        long w = sl.writeLock();
        sl.unlockWrite(w);
        System.out.println("valid after write?  " + sl.validate(s));
    }
}

import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

public class CasDemo {
    // A lock-free "set to the maximum" built from compareAndSet.
    static void updateMax(AtomicInteger max, int candidate) {
        int current = max.get();
        while (candidate > current) {
            if (max.compareAndSet(current, candidate)) return;   // we won the race
            current = max.get();                                  // someone changed it: retry
        }
    }

    // A tiny lock-free stack (Treiber stack) built on AtomicReference.
    static class Stack<T> {
        private record Node<T>(T value, Node<T> next) {}
        private final AtomicReference<Node<T>> head = new AtomicReference<>();

        void push(T v) {
            Node<T> oldHead, newHead;
            do {
                oldHead = head.get();
                newHead = new Node<>(v, oldHead);
            } while (!head.compareAndSet(oldHead, newHead));
        }

        T pop() {
            Node<T> oldHead;
            do {
                oldHead = head.get();
                if (oldHead == null) return null;
            } while (!head.compareAndSet(oldHead, oldHead.next()));
            return oldHead.value();
        }
    }

    public static void main(String[] args) throws Exception {
        AtomicInteger n = new AtomicInteger(5);
        System.out.println("CAS 5->6: " + n.compareAndSet(5, 6) + ", value " + n.get());
        System.out.println("CAS 5->7: " + n.compareAndSet(5, 7) + ", value " + n.get());
        System.out.println("updateAndGet(x*10) = " + n.updateAndGet(x -> x * 10));
        System.out.println("accumulateAndGet(max with 3) = " + n.accumulateAndGet(3, Math::max));

        AtomicInteger max = new AtomicInteger(Integer.MIN_VALUE);
        Thread[] ts = new Thread[4];
        for (int t = 0; t < ts.length; t++) {
            final int base = t * 1000;
            ts[t] = new Thread(() -> { for (int i = 0; i < 1000; i++) updateMax(max, base + i); });
            ts[t].start();
        }
        for (Thread t : ts) t.join();
        System.out.println("max = " + max.get());

        Stack<String> s = new Stack<>();
        s.push("a"); s.push("b"); s.push("c");
        System.out.println(s.pop() + s.pop() + s.pop() + " " + s.pop());
    }
}

import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.LongAdder;

public class CounterRace {
    static int plain;
    static volatile int vol;
    static int locked;
    static final Object LOCK = new Object();
    static final AtomicLong atomic = new AtomicLong();
    static final LongAdder adder = new LongAdder();

    static void runThreads(int threads, Runnable task) throws InterruptedException {
        Thread[] ts = new Thread[threads];
        for (int i = 0; i < threads; i++) { ts[i] = new Thread(task); ts[i].start(); }
        for (Thread t : ts) t.join();
    }

    public static void main(String[] args) throws Exception {
        int threads = 4, perThread = 500_000;
        long expected = (long) threads * perThread;

        runThreads(threads, () -> { for (int i = 0; i < perThread; i++) plain++; });
        runThreads(threads, () -> { for (int i = 0; i < perThread; i++) vol++; });
        runThreads(threads, () -> {
            for (int i = 0; i < perThread; i++) synchronized (LOCK) { locked++; }
        });
        runThreads(threads, () -> {
            for (int i = 0; i < perThread; i++) atomic.incrementAndGet();
        });
        runThreads(threads, () -> {
            for (int i = 0; i < perThread; i++) adder.increment();
        });

        System.out.println("expected      = " + expected);
        System.out.println("plain int     correct? " + (plain == expected));
        System.out.println("volatile int  correct? " + (vol == expected));
        System.out.println("synchronized  = " + locked);
        System.out.println("AtomicLong    = " + atomic.get());
        System.out.println("LongAdder     = " + adder.sum());
    }
}

import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicStampedReference;

public class AbaDemo {
    public static void main(String[] args) {
        // Plain CAS cannot see A -> B -> A.
        AtomicInteger value = new AtomicInteger(100);
        int seen = value.get();                 // thread 1 reads 100 and is paused
        value.compareAndSet(100, 50);           // thread 2: 100 -> 50
        value.compareAndSet(50, 100);           // thread 2: 50 -> 100 (looks untouched)
        System.out.println("plain CAS succeeds despite A-B-A: " + value.compareAndSet(seen, 999));

        // A stamp (version) makes the change visible.
        AtomicStampedReference<Integer> ref = new AtomicStampedReference<>(100, 0);
        int[] stampHolder = new int[1];
        Integer seenValue = ref.get(stampHolder);
        int seenStamp = stampHolder[0];
        ref.compareAndSet(100, 50, ref.getStamp(), ref.getStamp() + 1);
        ref.compareAndSet(50, 100, ref.getStamp(), ref.getStamp() + 1);
        boolean ok = ref.compareAndSet(seenValue, 999, seenStamp, seenStamp + 1);
        System.out.println("stamped CAS succeeds: " + ok + ", stamp now " + ref.getStamp());
    }
}

