public class PoolBasics {
    record Order(int id, int amount) {}

    static int price(Order o) throws InterruptedException {
        Thread.sleep(50);                       // pretend to call a pricing service
        if (o.id() == 3) throw new IllegalStateException("order 3 is invalid");
        return o.amount() * 2;
    }

    public static void main(String[] args) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(3);
        try {
            List<Future<Integer>> futures = new ArrayList<>();
            for (int i = 1; i <= 4; i++) {
                Order order = new Order(i, i * 10);
                Callable<Integer> task = () -> price(order);
                futures.add(pool.submit(task));
            }
            for (int i = 0; i < futures.size(); i++) {
                try {
                    System.out.println("order " + (i + 1) + " -> " + futures.get(i).get());
                } catch (ExecutionException e) {
                    System.out.println("order " + (i + 1) + " failed: " + e.getCause());
                }
            }

            Future<String> slow = pool.submit(() -> { Thread.sleep(2000); return "late"; });
            try {
                slow.get(100, TimeUnit.MILLISECONDS);
            } catch (TimeoutException e) {
                System.out.println("timed out, cancelling: " + slow.cancel(true));
                System.out.println("isCancelled = " + slow.isCancelled()
                        + ", isDone = " + slow.isDone());
            }

            List<Callable<String>> jobs = List.of(() -> "A", () -> "B", () -> "C");
            for (Future<String> f : pool.invokeAll(jobs)) System.out.print(f.get() + " ");
            System.out.println("<- invokeAll keeps submission order");
            System.out.println("invokeAny returned one of A/B/C: "
                    + List.of("A", "B", "C").contains(pool.invokeAny(jobs)));
        } finally {
