        }
    }
}

import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class TpeDemo {
    static void fill(ThreadPoolExecutor pool, int tasks, CountDownLatch gate) {
        for (int i = 1; i <= tasks; i++) {
            final int id = i;
            try {
                pool.execute(() -> {
                    try { gate.await(); } catch (InterruptedException e) { /* ignore */ }
                });
                System.out.printf("task %d accepted: pool=%d active=%d queued=%d%n",
                        id, pool.getPoolSize(), pool.getActiveCount(), pool.getQueue().size());
            } catch (RejectedExecutionException e) {
                System.out.printf("task %d REJECTED (pool=%d, queued=%d)%n",
                        id, pool.getPoolSize(), pool.getQueue().size());
            }
        }
    }

    static void scenario(String title, ThreadPoolExecutor pool) throws Exception {
        System.out.println("--- " + title);
        CountDownLatch gate = new CountDownLatch(1);   // keeps every task busy until we open it
        fill(pool, 7, gate);
        gate.countDown();
        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);
        System.out.println("completed tasks = " + pool.getCompletedTaskCount());
    }

    public static void main(String[] args) throws Exception {
        // core 2, max 4, queue of 2: tasks 1-2 start core threads, 3-4 are queued,
        // 5-6 create extra threads (up to max), 7 has nowhere to go.
        scenario("AbortPolicy (default)", new ThreadPoolExecutor(2, 4, 30, TimeUnit.SECONDS,
                new ArrayBlockingQueue<>(2), new ThreadPoolExecutor.AbortPolicy()));
        scenario("DiscardPolicy (task 7 is silently dropped)",
                new ThreadPoolExecutor(2, 4, 30, TimeUnit.SECONDS,
                new ArrayBlockingQueue<>(2), new ThreadPoolExecutor.DiscardPolicy()));
    }
}

