public class CallerRunsDemo {
    public static void main(String[] args) throws Exception {
        // One worker, hand-off queue, CallerRunsPolicy: when the worker is busy, the
        // submitting thread runs the task itself, which slows the producer down (back-pressure).
        ThreadPoolExecutor pool = new ThreadPoolExecutor(1, 1, 0, TimeUnit.SECONDS,
                new SynchronousQueue<>(), new ThreadPoolExecutor.CallerRunsPolicy());
        CountDownLatch gate = new CountDownLatch(1);
        pool.execute(() -> {
            try { gate.await(); } catch (InterruptedException e) { /* ignore */ }
        });
        pool.execute(() ->
                System.out.println("task B ran on: " + Thread.currentThread().getName()));
        gate.countDown();
        pool.shutdown();
        pool.awaitTermination(2, TimeUnit.SECONDS);
    }
}

import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ShutdownDemo {
    public static void main(String[] args) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(1);
        pool.execute(() -> {
            try {
                Thread.sleep(300);
                System.out.println("task 1 finished normally");
            } catch (InterruptedException e) {
                System.out.println("task 1 interrupted");
            }
        });
        pool.execute(() -> System.out.println("task 2 (was queued)"));

        pool.shutdown();                                  // no new tasks; queued ones still run
        System.out.println("isShutdown = " + pool.isShutdown()
                + ", isTerminated = " + pool.isTerminated());
        try {
            pool.execute(() -> System.out.println("never"));
        } catch (java.util.concurrent.RejectedExecutionException e) {
            System.out.println("submit after shutdown -> RejectedExecutionException");
        }
        boolean done = pool.awaitTermination(1, TimeUnit.SECONDS);
        System.out.println("terminated in time = " + done);

        // The robust shutdown recipe (also what ExecutorService.close() does in Java 19+).
        ExecutorService pool2 = Executors.newFixedThreadPool(1);
        pool2.execute(() -> {
            try { Thread.sleep(10_000); } catch (InterruptedException e) {
                System.out.println("long task interrupted by shutdownNow");
            }
        });
        Thread.sleep(100);
        pool2.shutdown();
        if (!pool2.awaitTermination(200, TimeUnit.MILLISECONDS)) {
            List<Runnable> neverStarted = pool2.shutdownNow();
            System.out.println("never started: " + neverStarted.size());
            pool2.awaitTermination(1, TimeUnit.SECONDS);
        }

        try (ExecutorService pool3 = Executors.newFixedThreadPool(2)) {   // Java 19+
            pool3.submit(() -> System.out.println("try-with-resources waits for this task"));
        }
        System.out.println("after close()");
    }
}

