import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class CfBasics {
    static void sleep(long ms) {
        try {
            Thread.sleep(ms);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    static CompletableFuture<Integer> price(ExecutorService ex, String sku) {
        return CompletableFuture.supplyAsync(() -> { sleep(100); return sku.length() * 100; }, ex);
    }

    static CompletableFuture<String> stock(ExecutorService ex, String sku) {
        return CompletableFuture.supplyAsync(() -> { sleep(100); return "in stock"; }, ex);
    }

    static CompletableFuture<Double> rating(ExecutorService ex, String sku) {
        return CompletableFuture.supplyAsync(() -> { sleep(100); return 4.5; }, ex);
    }

    public static void main(String[] args) {
        ExecutorService ex = Executors.newFixedThreadPool(4);
        try {
            long t0 = System.nanoTime();

            // thenApply: transform the result (like Stream.map / Optional.map)
            CompletableFuture<String> label = price(ex, "book")
                    .thenApply(cents -> cents / 100.0)
                    .thenApply(d -> "price: " + d);
            System.out.println(label.join());

            // thenCompose: the next step itself returns a CompletableFuture (flatMap)
            CompletableFuture<String> chained = price(ex, "pen")
                    .thenCompose(p -> stock(ex, "pen").thenApply(s -> p + " / " + s));
            System.out.println("composed: " + chained.join());

            // thenCombine: wait for two INDEPENDENT futures, then merge
            CompletableFuture<String> both = price(ex, "lamp")
                    .thenCombine(rating(ex, "lamp"), (p, r) -> "lamp " + p + " rated " + r);
            System.out.println(both.join());

            // allOf: wait for many; the result is Void, so read each future afterwards
            long t1 = System.nanoTime();
            var p = price(ex, "desk");
            var s = stock(ex, "desk");
            var r = rating(ex, "desk");
            CompletableFuture.allOf(p, s, r).join();
            long millis = (System.nanoTime() - t1) / 1_000_000;
            System.out.println("allOf: " + p.join() + ", " + s.join() + ", " + r.join());
            System.out.println("three 100 ms calls took less than 250 ms: " + (millis < 250));

            // anyOf: the first one to finish wins (result type is Object)
            CompletableFuture<Object> first = CompletableFuture.anyOf(
                    CompletableFuture.supplyAsync(() -> { sleep(300); return "slow"; }, ex),
                    CompletableFuture.supplyAsync(() -> { sleep(30); return "fast"; }, ex));
            System.out.println("anyOf -> " + first.join());

            // Collect a list of futures into a future of a list
            List<CompletableFuture<Integer>> prices = List.of("a", "bb", "ccc").stream()
                    .map(k -> price(ex, k)).toList();
            CompletableFuture<List<Integer>> all = CompletableFuture
                    .allOf(prices.toArray(new CompletableFuture[0]))
                    .thenApply(v -> prices.stream().map(CompletableFuture::join).toList());
            System.out.println("all prices: " + all.join());
        } finally {
            ex.shutdown();
        }
    }
}

