        }
    }
}

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;

public class CfErrors {
    static CompletableFuture<Integer> failing() {
        return CompletableFuture.supplyAsync(() -> {
            if (true) throw new IllegalStateException("pricing service down");
            return 1;
        });
    }

    public static void main(String[] args) throws Exception {
        // 1. Without handling, the failure travels down the chain and surfaces at join()/get().
        CompletableFuture<Integer> doomed = failing().thenApply(x -> x + 1);
        try {
            doomed.join();
        } catch (CompletionException e) {
            System.out.println("join() threw CompletionException, cause: " + e.getCause());
        }
        try {
            doomed.get();
        } catch (ExecutionException e) {
            System.out.println("get()  threw ExecutionException,  cause: " + e.getCause());
        }

        // 2. exceptionally: recover with a fallback value
        int recovered = failing().exceptionally(ex -> -1).join();
        System.out.println("exceptionally -> " + recovered);

        // 3. handle: sees BOTH result and exception, returns a new value
        String msg = failing()
                .handle((v, ex) -> ex == null ? "ok " + v
                        : "failed: " + ex.getClass().getSimpleName()
                        + " / " + ex.getCause().getMessage())
                .join();
        System.out.println("handle -> " + msg);

        // 4. whenComplete: observe (log) but do not change the outcome
        try {
            failing().whenComplete((v, ex) ->
                    System.out.println("whenComplete saw: " + ex.getClass().getSimpleName()))
                    .join();
        } catch (CompletionException e) {
            System.out.println("still failed afterwards: " + e.getCause().getMessage());
        }

        // 5. Timeouts (Java 9+)
        CompletableFuture<String> slow = CompletableFuture.supplyAsync(() -> {
            try { Thread.sleep(1000); } catch (InterruptedException e) { /* ignore */ }
            return "slow result";
        });
        String r = slow.completeOnTimeout("default", 100, TimeUnit.MILLISECONDS).join();
        System.out.println("completeOnTimeout -> " + r);

        CompletableFuture<String> slow2 = CompletableFuture.supplyAsync(() -> {
            try { Thread.sleep(1000); } catch (InterruptedException e) { /* ignore */ }
            return "slow result";
        }).orTimeout(100, TimeUnit.MILLISECONDS);
        try {
            slow2.join();
        } catch (CompletionException e) {
            System.out.println("orTimeout -> " + e.getCause().getClass().getSimpleName());
        }

        // 6. You can complete a future by hand: it is also a promise.
        CompletableFuture<String> promise = new CompletableFuture<>();
        promise.completeExceptionally(new RuntimeException("cancelled by user"));
        System.out.println("isCompletedExceptionally = " + promise.isCompletedExceptionally());
    }
}

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class CfStarve {
    public static void main(String[] args) throws Exception {
        // Daemon worker: join() ignores interrupts, so a stuck worker would keep the JVM alive.
        ExecutorService single = Executors.newFixedThreadPool(1, r -> {
            Thread t = new Thread(r, "single");
            t.setDaemon(true);
            return t;
        });
        try {
            // BAD: the outer task occupies the only worker, then waits for an inner task
            // that needs that same worker.
            CompletableFuture<Integer> outer = CompletableFuture.supplyAsync(() -> {
                CompletableFuture<Integer> inner = CompletableFuture.supplyAsync(() -> 42, single);
                return inner.join() + 1;
            }, single);
            try {
                outer.get(500, TimeUnit.MILLISECONDS);
            } catch (java.util.concurrent.TimeoutException e) {
                System.out.println("blocking style: stuck (timed out after 500 ms)");
            }

            // GOOD: compose instead of blocking. No thread waits, so one worker is enough.
            ExecutorService single2 = Executors.newFixedThreadPool(1);
            int ok = CompletableFuture.supplyAsync(() -> 1, single2)
                    .thenCompose(x -> CompletableFuture.supplyAsync(() -> x + 41, single2))
                    .thenApply(x -> x + 1)
                    .get(2, TimeUnit.SECONDS);
            System.out.println("composed style: " + ok);
            single2.shutdown();
        } finally {
            single.shutdownNow();
        }
    }
}

import java.util.concurrent.BrokenBarrierException;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.atomic.AtomicInteger;

public class LatchBarrier {
    public static void main(String[] args) throws Exception {
        // CountDownLatch: one-shot. Workers wait for a start signal; main waits for all to finish.
        int workers = 3;
        CountDownLatch startSignal = new CountDownLatch(1);
        CountDownLatch done = new CountDownLatch(workers);
        AtomicInteger finished = new AtomicInteger();
        for (int i = 0; i < workers; i++) {
            new Thread(() -> {
                try {
                    startSignal.await();               // all workers park here
                    finished.incrementAndGet();        // pretend work
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                } finally {
                    done.countDown();                  // count down even on failure
                }
            }).start();
        }
        System.out.println("finished before the signal = " + finished.get());
        startSignal.countDown();                       // release everybody at once
        done.await();
        System.out.println("finished after the latch   = " + finished.get());
        System.out.println("latch count now " + done.getCount() + " (cannot be reset)");
        // CyclicBarrier: reusable; every party waits until all arrive, then a barrier action runs.
        CyclicBarrier barrier =
                new CyclicBarrier(3, () -> System.out.println("  -- barrier tripped"));
        Thread[] ts = new Thread[3];
        for (int i = 0; i < 3; i++) {
            ts[i] = new Thread(() -> {
                try {
                    for (int round = 1; round <= 2; round++) {
                        barrier.await();               // phase 1 / phase 2 boundaries
                    }
                } catch (InterruptedException | BrokenBarrierException e) {
                    Thread.currentThread().interrupt();
                }
            });
            ts[i].start();
        }
        for (Thread t : ts) t.join();
        System.out.println("barrier reused for 2 rounds");
    }
}

import java.util.concurrent.Exchanger;
import java.util.concurrent.Phaser;
import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicInteger;

public class SemaphorePhaser {
    public static void main(String[] args) throws Exception {
        // Semaphore: at most 3 threads inside the section at once (e.g. a connection limit).
        Semaphore permits = new Semaphore(3);
        AtomicInteger inside = new AtomicInteger();
        AtomicInteger maxInside = new AtomicInteger();
        Thread[] ts = new Thread[10];
        for (int i = 0; i < ts.length; i++) {
            ts[i] = new Thread(() -> {
                try {
                    permits.acquire();
                    try {
                        int now = inside.incrementAndGet();
                        maxInside.accumulateAndGet(now, Math::max);
                        Thread.sleep(30);
                        inside.decrementAndGet();
                    } finally {
                        permits.release();
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
            ts[i].start();
        }
        for (Thread t : ts) t.join();
        System.out.println("10 threads, 3 permits -> max inside at once = " + maxInside.get());
        System.out.println("tryAcquire(5) on 3 free permits: " + permits.tryAcquire(5));

        // Phaser: like a barrier, but parties can register/deregister dynamically.
        Phaser phaser = new Phaser(1);                    // main registers itself
        for (int i = 1; i <= 2; i++) {
            final int id = i;
            phaser.register();
            new Thread(() -> {
                phaser.arriveAndAwaitAdvance();           // end of phase 0
                phaser.arriveAndDeregister();             // leave after phase 1
            }, "worker-" + id).start();
        }
        System.out.println("phase before = " + phaser.getPhase());
        phaser.arriveAndAwaitAdvance();                   // main joins the phase-0 rendezvous
        System.out.println("phase after  = " + phaser.getPhase());
        phaser.arriveAndDeregister();

        // Exchanger: two threads swap objects at a meeting point.
        Exchanger<String> ex = new Exchanger<>();
        Thread other = new Thread(() -> {
            try { System.out.println("other got: " + ex.exchange("from-other")); }
            catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });
        other.start();
        String got = ex.exchange("from-main");
        other.join();
        System.out.println("main got:  " + got);
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.PriorityBlockingQueue;
import java.util.concurrent.SynchronousQueue;
import java.util.concurrent.TimeUnit;

public class QueuesDemo {
    static final String POISON = "<<STOP>>";

    public static void main(String[] args) throws Exception {
        BlockingQueue<String> queue = new ArrayBlockingQueue<>(2);   // bounded: back-pressure
        List<String> consumed = Collections.synchronizedList(new ArrayList<>());

        Thread consumer = new Thread(() -> {
            try {
                while (true) {
                    String item = queue.take();                      // blocks while empty
                    if (item.equals(POISON)) break;                  // poison pill ends the loop
                    consumed.add(item);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        consumer.start();
        for (int i = 1; i <= 5; i++) queue.put("order-" + i);        // blocks while full
        queue.put(POISON);
        consumer.join();
        System.out.println("consumed: " + consumed);

        // The four flavours of insertion on a full queue.
        BlockingQueue<Integer> small = new ArrayBlockingQueue<>(1);
        small.add(1);
        System.out.println("offer(2)           = " + small.offer(2));
        System.out.println("offer(2, 50ms)     = " + small.offer(2, 50, TimeUnit.MILLISECONDS));
        try {
            small.add(2);
        } catch (IllegalStateException e) {
            System.out.println("add(2) throws     : " + e.getMessage());
        }
        System.out.println("poll()             = " + small.poll());
        System.out.println("poll(50ms) on empty = " + small.poll(50, TimeUnit.MILLISECONDS));

        // PriorityBlockingQueue: ordered, unbounded.
        BlockingQueue<Integer> pq = new PriorityBlockingQueue<>(List.of(5, 1, 3));
        System.out.println("priority order: " + pq.take() + " " + pq.take() + " " + pq.take());

        // SynchronousQueue: no storage, a pure hand-off.
        SynchronousQueue<String> handoff = new SynchronousQueue<>();
        System.out.println("offer with no waiting consumer = " + handoff.offer("x"));
        Thread taker = new Thread(() -> {
            try { System.out.println("taker received " + handoff.take()); }
            catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });
        taker.start();
        handoff.put("parcel");                       // returns when the taker took it
        taker.join();
    }
}

