import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.LongAdder;

public class ChmDemo {
    static void inParallel(int threads, Runnable r) throws InterruptedException {
        Thread[] ts = new Thread[threads];
        for (int i = 0; i < threads; i++) { ts[i] = new Thread(r); ts[i].start(); }
        for (Thread t : ts) t.join();
    }
    public static void main(String[] args) throws Exception {
        int threads = 4, perThread = 50_000;

        // BROKEN: check-then-act with individually atomic get and put.
        Map<String, Integer> broken = new ConcurrentHashMap<>();
        inParallel(threads, () -> {
            for (int i = 0; i < perThread; i++) {
                Integer old = broken.get("hits");
                broken.put("hits", old == null ? 1 : old + 1);   // another thread may interleave
            }
        });

        // CORRECT: one atomic operation.
        ConcurrentHashMap<String, Integer> merged = new ConcurrentHashMap<>();
        inParallel(threads, () -> {
            for (int i = 0; i < perThread; i++) merged.merge("hits", 1, Integer::sum);
        });

        // ALSO CORRECT and scalable: map of LongAdder.
        ConcurrentHashMap<String, LongAdder> adders = new ConcurrentHashMap<>();
        inParallel(threads, () -> {
            for (int i = 0; i < perThread; i++) {
                adders.computeIfAbsent("hits", k -> new LongAdder()).increment();
            }
        });

        long expected = (long) threads * perThread;
        System.out.println("expected             = " + expected);
        System.out.println("get+put lost updates? " + (broken.get("hits") != expected));
        System.out.println("merge                = " + merged.get("hits"));
        System.out.println("computeIfAbsent+Adder = " + adders.get("hits").sum());

        ConcurrentHashMap<String, Integer> stock = new ConcurrentHashMap<>();
        System.out.println("putIfAbsent first:  " + stock.putIfAbsent("pen", 10)); // null: absent
        System.out.println("putIfAbsent second: " + stock.putIfAbsent("pen", 99)); // old value
        stock.compute("pen", (k, v) -> v == null ? 1 : v - 3);
        System.out.println("after compute: " + stock);
        System.out.println("replace(pen, 7, 70): " + stock.replace("pen", 7, 70));
        System.out.println("remove(pen, 1): " + stock.remove("pen", 1));
        stock.put("ink", 5);
        stock.put("tape", 8);
        System.out.println("mappingCount = " + stock.mappingCount() + ", size = " + stock.size());

        // Bulk operations take a parallelism threshold (here 1 = use parallelism when possible).
        long total = stock.reduceValues(1, Integer::sum);
        System.out.println("reduceValues sum = " + total);
        System.out.println("search value > 50 -> " + stock.search(1, (k, v) -> v > 50 ? k : null));

        try {
            stock.put("null-value", null);
        } catch (NullPointerException e) {
            System.out.println("ConcurrentHashMap rejects null values (and null keys)");
        }
        Map<String, Integer> hm = new HashMap<>();
        hm.put(null, null);
        System.out.println("HashMap allows them: " + hm);
    }
}

import java.util.ArrayList;
import java.util.ConcurrentModificationException;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

public class CowDemo {
    public static void main(String[] args) {
        List<String> plain = new ArrayList<>(List.of("a", "b", "c"));
        try {
            for (String s : plain) if (s.equals("a")) plain.add("d");
        } catch (ConcurrentModificationException e) {
            System.out.println("ArrayList: ConcurrentModificationException");
        }

        List<String> cow = new CopyOnWriteArrayList<>(List.of("a", "b", "c"));
        for (String s : cow) {
            if (s.equals("a")) cow.add("d");          // legal: the iterator uses a snapshot
            System.out.print(s + " ");
        }
        System.out.println("-> list is now " + cow);

        var it = cow.iterator();
        cow.add("e");
        int seen = 0;
        while (it.hasNext()) { it.next(); seen++; }
        System.out.println("iterator made before add('e') saw " + seen
                + " elements; list has " + cow.size());
        try {
            it = cow.iterator();
            it.next();
            it.remove();
        } catch (UnsupportedOperationException e) {
            System.out.println("snapshot iterator does not support remove()");
        }
    }
}

import java.time.Duration;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.IntStream;

public class VtBasics {
    static long runTasks(ExecutorService ex, int tasks, AtomicInteger done) {
        long t0 = System.nanoTime();
        try (ex) {                                           // close() waits for all tasks
            IntStream.range(0, tasks).forEach(i -> ex.submit(() -> {
                try { Thread.sleep(Duration.ofMillis(100)); }   // simulated blocking I/O
                catch (InterruptedException e) { Thread.currentThread().interrupt(); }
                done.incrementAndGet();
            }));
        }
        return (System.nanoTime() - t0) / 1_000_000;
    }

    public static void main(String[] args) throws Exception {
        Thread vt = Thread.ofVirtual().name("order-handler").start(() ->
                System.out.println("inside: isVirtual=" + Thread.currentThread().isVirtual()
                        + ", daemon=" + Thread.currentThread().isDaemon()));
        vt.join();
        Thread unstarted = Thread.ofVirtual().unstarted(() -> {});
        System.out.println("state before start: " + unstarted.getState());
        Thread pt = Thread.ofPlatform().name("legacy").start(() -> {});
        pt.join();
        System.out.println("virtual thread name when unnamed: '"
                + Thread.startVirtualThread(() -> {}).getName() + "'");

        int tasks = 2000;
        AtomicInteger platformDone = new AtomicInteger();
        long platformMs = runTasks(Executors.newFixedThreadPool(100), tasks, platformDone);
        AtomicInteger virtualDone = new AtomicInteger();
        long virtualMs = runTasks(Executors.newVirtualThreadPerTaskExecutor(), tasks, virtualDone);

        System.out.println("platform pool of 100: " + platformDone + " tasks done");
        System.out.println("virtual threads:      " + virtualDone + " tasks done");
        System.out.printf("typical timings: platform pool %d ms, virtual threads %d ms%n",
                platformMs, virtualMs);
    }
}

import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class VtServer {
    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        // Thread-per-request: every request gets its own virtual thread.
        server.setExecutor(Executors.newVirtualThreadPerTaskExecutor());
        server.createContext("/order", exchange -> {
            try {
                Thread.sleep(200);                       // pretend to call a database
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            byte[] body = ("virtual=" + Thread.currentThread().isVirtual())
                    .getBytes(StandardCharsets.UTF_8);
            exchange.sendResponseHeaders(200, body.length);
            try (var out = exchange.getResponseBody()) { out.write(body); }
        });
        server.start();
        URI uri = URI.create("http://127.0.0.1:" + server.getAddress().getPort() + "/order");

        HttpClient client = HttpClient.newHttpClient();
        long t0 = System.nanoTime();
        int ok = 0;
        try (ExecutorService callers = Executors.newVirtualThreadPerTaskExecutor()) {
            List<Future<HttpResponse<String>>> results = new ArrayList<>();
            for (int i = 0; i < 300; i++) {
                results.add(callers.submit(() -> client.send(HttpRequest.newBuilder(uri).build(),
                        HttpResponse.BodyHandlers.ofString())));
            }
            for (var f : results) {
                var r = f.get();
                if (r.statusCode() == 200 && r.body().equals("virtual=true")) ok++;
            }
        }
        long ms = (System.nanoTime() - t0) / 1_000_000;
        System.out.println(ok + " of 300 requests answered by a virtual thread");
        System.out.println("each request blocks 200 ms; total " + ms + " ms (serial: 60000 ms)");
        server.stop(0);
    }
}

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.locks.ReentrantLock;

public class VtPinning {
    static void sleep() {
        try { Thread.sleep(Duration.ofMillis(200)); }
        catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }

    static long run(boolean useSynchronized) throws Exception {
        List<Thread> threads = new ArrayList<>();
        long t0 = System.nanoTime();
        for (int i = 0; i < 8; i++) {
            final Object monitor = new Object();             // private lock: no contention
            final ReentrantLock lock = new ReentrantLock();
            threads.add(Thread.ofVirtual().start(() -> {
                if (useSynchronized) {
                    synchronized (monitor) { sleep(); }      // blocks while holding a monitor
                } else {
                    lock.lock();
                    try { sleep(); } finally { lock.unlock(); }
                }
            }));
        }
        for (Thread t : threads) t.join();
        return (System.nanoTime() - t0) / 1_000_000;
    }

    public static void main(String[] args) throws Exception {
        // Must run before the first virtual thread starts (or pass -D flags on the command line).
        System.setProperty("jdk.virtualThreadScheduler.parallelism", "2");
        System.setProperty("jdk.virtualThreadScheduler.maxPoolSize", "2");
        System.out.println("8 virtual threads, each sleeps 200 ms, only 2 carrier threads");
        System.out.println("typical: with ReentrantLock  -> " + run(false) + " ms");
        System.out.println("typical: with synchronized   -> " + run(true) + " ms");
    }
}
